(function(root){
  'use strict';
  const BASE=2648.32, FEE=.001, MAINT=.05;
  function init(s){s.protocol??={block:0,day:0,mark:BASE,index:BASE,funding:0,positions:[],closed:[],loans:[],repaid:0,defaults:0,pool:null,events:[]};return s.protocol;}
  function positive(n){if(!Number.isFinite(n)||n<=0)throw Error('Enter an amount greater than zero.');}
  function ready(s){if(!s.connected)throw Error('Start your demo account first.');return init(s);}
  function debit(s,n){if(n>s.balances.USDC+1e-8)throw Error('Insufficient available USDC.');s.balances.USDC-=n;}
  function event(s,text){const p=init(s);p.events.unshift({block:p.block,day:p.day,text});p.events=p.events.slice(0,30);}
  function equity(p,mark){return p.margin+p.qty*(mark-p.entry)*(p.side==='long'?1:-1);}
  function liquidation(p){const d=p.side==='long'?1:-1;return(p.qty*p.entry*d-p.margin)/(p.qty*(d-MAINT));}
  function open(s,margin,leverage,side){const p=ready(s);positive(margin);if(![1,2,3,5,10].includes(leverage)||!['long','short'].includes(side))throw Error('Choose a valid leverage and direction.');const notional=margin*leverage;debit(s,margin+notional*FEE);p.positions.push({id:crypto.randomUUID(),side,margin,initial:margin,qty:notional/p.mark,entry:p.mark,leverage,funding:0,fee:notional*FEE});event(s,`Opened ${leverage}× ${side}: ${margin.toFixed(2)} USDC margin.`);}
  function close(s,id,liquidated=false){const p=ready(s),pos=p.positions.find(x=>x.id===id);if(!pos)throw Error('Position is no longer open.');const value=equity(pos,p.mark),fee=pos.qty*p.mark*FEE,returned=liquidated?0:Math.max(0,value-fee);s.balances.USDC+=returned;p.positions=p.positions.filter(x=>x.id!==id);p.closed.unshift({...pos,exit:p.mark,pnl:returned-pos.initial-pos.fee,status:liquidated?'Liquidated':'Closed'});p.closed=p.closed.slice(0,20);event(s,`${liquidated?'Liquidated':'Closed'} ${pos.side} position; returned ${returned.toFixed(2)} USDC.`);}
  function block(s,move){const p=ready(s);if(![-5,-1,0,1,5].includes(move))throw Error('Invalid market scenario.');p.block++;p.index=Math.max(1,p.index*(1+move/100));p.mark=p.index*(1+Math.sin(p.block*.9)*.002);p.funding=Math.max(-.0001,Math.min(.0001,(p.mark-p.index)/p.index/20));for(const pos of [...p.positions]){const payment=pos.qty*p.mark*p.funding*(pos.side==='long'?1:-1);pos.margin-=payment;pos.funding+=payment;if(equity(pos,p.mark)<=pos.qty*p.mark*MAINT)close(s,pos.id,true);}event(s,`Block ${p.block}: mark ${p.mark.toFixed(2)}; funding ${(p.funding*100).toFixed(5)}%.`);}
  function terms(s){const p=init(s);const score=Math.max(300,Math.min(850,560+Math.min(60,s.history.length*5)+Math.min(150,p.repaid*30)-p.defaults*100));return{score,limit:score>=700?3000:score>=600?1500:500,apr:score>=700?.08:score>=600?.12:.18,collateral:score>=700?.25:score>=600?.4:.6};}
  function debt(p,l){return l.principal*(1+l.apr*(p.day-l.day)/365);}
  function borrow(s,n){const p=ready(s);positive(n);if(p.loans.length)throw Error('Repay your active loan before borrowing again.');const t=terms(s);if(n>t.limit)throw Error(`Your current credit limit is ${t.limit} USDC.`);const collateral=n*t.collateral;debit(s,collateral);s.balances.USDC+=n;p.loans.push({id:crypto.randomUUID(),principal:n,collateral,apr:t.apr,day:p.day,due:p.day+30,late:false});event(s,`Borrowed ${n.toFixed(2)} USDC with ${collateral.toFixed(2)} collateral.`);}
  function days(s,n){const p=ready(s);if(![1,7,30].includes(n))throw Error('Invalid day increment.');p.day+=n;for(const l of p.loans){if(p.day>l.due&&!l.late){l.late=true;p.defaults++;event(s,'Loan overdue: credit score reduced; debt remains outstanding.');}}event(s,`Simulation advanced ${n} days; loan interest accrued.`);}
  function repay(s,id){const p=ready(s),l=p.loans.find(x=>x.id===id);if(!l)throw Error('Loan is no longer active.');const due=debt(p,l);if(s.balances.USDC+l.collateral+1e-8<due)throw Error('Insufficient USDC including released collateral to repay.');s.balances.USDC+=l.collateral-due;p.loans=[];if(!l.late&&p.day-l.day>=7)p.repaid++;event(s,`Repaid ${due.toFixed(2)} USDC; released ${l.collateral.toFixed(2)} collateral.`);}
  function deposit(s,n){const p=ready(s);positive(n);if(p.pool)throw Error('Withdraw the existing vault before creating another.');const eth=n/p.mark;if(s.balances.ETH+1e-8<eth)throw Error(`You need ${eth.toFixed(4)} available ETH for this paired deposit.`);debit(s,n);s.balances.ETH-=eth;p.pool={usd:n,eth,initialUsd:n,initialEth:eth,fees:0,fills:0};event(s,`Deposited ${n.toFixed(2)} USDC and ${eth.toFixed(4)} ETH into the maker vault.`);}
  function quote(s){const p=init(s),v=p.pool;if(!v)return null;const value=v.usd+v.eth*p.mark,weight=v.eth*p.mark/value,fee=.003+Math.min(.012,Math.abs(weight-.5)*.04);return{mid:v.usd/v.eth,fee,weight,value,hold:v.initialUsd+v.initialEth*p.mark,bid:v.usd/v.eth*(1-fee),ask:v.usd/v.eth/(1-fee)};}
  function fill(s,direction,n){const p=ready(s),v=p.pool;positive(n);if(!v)throw Error('Deposit liquidity first.');if(!['buy','sell'].includes(direction))throw Error('Invalid flow direction.');const q=quote(s);if(n>q.value*.2)throw Error('Keep sample flow below 20% of vault value.');let out;if(direction==='buy'){const net=n*(1-q.fee);out=v.eth*net/(v.usd+net);v.usd+=n;v.eth-=out;}else{const input=n/p.mark,net=input*(1-q.fee);out=v.usd*net/(v.eth+net);v.eth+=input;v.usd-=out;}v.fees+=n*q.fee;v.fills++;event(s,`External demo trader ${direction==='buy'?'bought':'sold'} ETH; ${n.toFixed(2)} USDC notional. Quotes rebalanced.`);}
  function withdraw(s){const p=ready(s),v=p.pool;if(!v)throw Error('No active liquidity vault.');s.balances.USDC+=v.usd;s.balances.ETH+=v.eth;p.pool=null;event(s,'Withdrew current ETH and USDC reserves, including retained fees.');}
  function extraValue(s){const p=init(s);return p.positions.reduce((a,x)=>a+Math.max(0,equity(x,p.mark)),0)+p.loans.reduce((a,l)=>a+l.collateral-debt(p,l),0)+(quote(s)?.value||0);}
  const api={init,open,close,block,equity,liquidation,terms,borrow,days,debt,repay,deposit,quote,fill,withdraw,extraValue};root.FluxEngine=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
